 8 };
 9 // Function to initialize the heap
10 void initHeap(struct MinHeap* heap) {
11     heap-&gt;size = 0;
12 }
13 // Function to get the index of the parent node
14 int parent(int i) {
15     return (i - 1) / 2;
16 }
