18 int leftChild(int i) {
19     return 2 * i + 1;
20 }
21 // Function to get the index of the right child
22 int rightChild(int i) {
23     return 2 * i + 2;
24 }
25 // Function to swap two elements
26 void swap(int* a, int* b) {
27     int temp = *a;
28     *a = *b;
29     *b = temp;
30 }
31 // Function to insert a new element into the heap
32 void insert(struct MinHeap* heap, int key) {
33     if (heap-&gt;size == MAX_SIZE) {
34         printf(&quot;Heap overflow! Cannot insert.\n&quot;);
35         return;
36     }
37     // Insert the new key at the end
38     int i = heap-&gt;size;
