47 void heapify(struct MinHeap* heap, int i) {
48     int l = leftChild(i);
49     int r = rightChild(i);
50     int smallest = i;
51     if (l &lt; heap-&gt;size &amp;&amp; heap-&gt;arr[l] &lt; heap-&gt;arr[smallest]) {
52         smallest = l;
53     }
54     if (r &lt; heap-&gt;size &amp;&amp; heap-&gt;arr[r] &lt; heap-&gt;arr[smallest]) {
55         smallest = r;
56     }
